/* Interactive read-only view of the demo workbook (data in js/xl-data.js, generated by tools/xl_export.py).
   Tabs switch sheets, clicking a cell shows its formula, the grid scrolls, frozen panes stay put, − / + zoom. */
(function () {
  "use strict";
  var B = window.XLBOOK, app = document.getElementById("xlapp");
  if (!B || !app) return;

  var HW = 40, HH = 22;                          // row-header width, column-header height at 100%
  var ZMIN = 0.8, ZMAX = 2.6, ZSTEP = 0.1;
  var START = {                                  // opening zoom and selected cell per sheet
    "Analysis": { zoom: 1.35, sel: [7, 3] },
    "Mouse data": { zoom: 1.35, sel: [4, 5] },
    "Method and source": { zoom: 1.25, sel: [1, 0] }
  };

  function esc(s) { return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;"); }
  function colName(c) { var s = ""; c += 1; while (c > 0) { s = String.fromCharCode(65 + (c - 1) % 26) + s; c = Math.floor((c - 1) / 26); } return s; }
  function px(n) { return (Math.round(n * 100) / 100) + "px"; }

  var sheets = B.sheets.map(function (sh) {
    var X = [0], Y = [0], map = {}, st = START[sh.name] || { zoom: 1.35, sel: [0, 0] };
    sh.cw.forEach(function (w) { X.push(X[X.length - 1] + w); });
    sh.rh.forEach(function (h) { Y.push(Y[Y.length - 1] + h); });
    sh.cells.forEach(function (c) { map[c[0] + "," + c[1]] = c; });
    return { d: sh, X: X, Y: Y, map: map, nr: sh.rh.length, nc: sh.cw.length, zoom: st.zoom, sel: st.sel.slice(), sx: 0, sy: 0 };
  });
  var cur = 0;

  app.setAttribute("data-prevent-swipe", "");
  app.innerHTML =
    '<div class="xl-bar"><i></i><span>' + esc(B.file) + "</span></div>" +
    '<div class="xl-fx"><span class="xl-name"></span><span class="xl-fxi">fx</span><span class="xl-formula"></span></div>' +
    '<div class="xl-view"><div class="xl-grid"></div></div>' +
    '<div class="xl-foot"><div class="xl-tabs">' +
    sheets.map(function (s, i) { return '<button type="button" data-i="' + i + '">' + esc(s.d.name) + "</button>"; }).join("") +
    '</div><div class="xl-zoom"><button type="button" data-z="-1" aria-label="Zoom out">−</button><span></span><button type="button" data-z="1" aria-label="Zoom in">+</button></div></div>';
  var view = app.querySelector(".xl-view"), grid = app.querySelector(".xl-grid"),
    nameBox = app.querySelector(".xl-name"), fxBox = app.querySelector(".xl-formula"), zoomLbl = app.querySelector(".xl-zoom span");

  /* ---- charts: drawn from the series the workbook's own charts point at ---- */
  function niceMax(v) {
    var raw = v * 1.05 / 8, p = Math.pow(10, Math.floor(Math.log10(raw))), f = raw / p;
    var step = (f <= 1 ? 1 : f <= 2 ? 2 : f <= 5 ? 5 : 10) * p;
    return { step: step, max: Math.ceil(v * 1.05 / step) * step };
  }
  function chartSVG(d, w, h) {
    var L = 66, R = w - 18, T = 44, Bm = h - 34, n = d.vals.length, sc = niceMax(Math.max.apply(null, d.vals));
    var cw = (R - L) / n, bw = cw / 2.5, o = "";
    o += '<rect x=".5" y=".5" width="' + (w - 1) + '" height="' + (h - 1) + '" fill="#fff" stroke="#D9D9D9"/>';
    o += '<text x="' + w / 2 + '" y="26" text-anchor="middle" font-size="13" fill="#404040">' + esc(d.title) + "</text>";
    for (var v = 0; v <= sc.max + 1e-9; v += sc.step) {
      var y = Bm - (Bm - T) * v / sc.max;
      o += '<line x1="' + L + '" x2="' + R + '" y1="' + y + '" y2="' + y + '" stroke="' + (v ? "#CCC" : "#9A9A9A") + '"' + (v ? ' stroke-dasharray="4 3"' : "") + "/>";
      o += '<text x="' + (L - 7) + '" y="' + (y + 4) + '" text-anchor="end" font-size="11" fill="#595959">' + Math.round(v).toLocaleString("en-US") + "</text>";
    }
    for (var i = 0; i <= n; i++) o += '<line x1="' + (L + cw * i) + '" x2="' + (L + cw * i) + '" y1="' + T + '" y2="' + Bm + '" stroke="#CCC" stroke-dasharray="4 3"/>';
    d.vals.forEach(function (val, k) {
      var bh = (Bm - T) * val / sc.max, x = L + cw * k + (cw - bw) / 2;
      o += '<rect x="' + x + '" y="' + (Bm - bh) + '" width="' + bw + '" height="' + bh + '" fill="' + d.color + '"><title>' + esc(d.cats[k]) + ": " + (Math.round(val * 10) / 10).toLocaleString("en-US") + "</title></rect>";
      o += '<text x="' + (L + cw * (k + .5)) + '" y="' + (Bm + 17) + '" text-anchor="middle" font-size="11" fill="#595959">' + esc(d.cats[k]) + "</text>";
    });
    o += '<text transform="translate(17 ' + (T + Bm) / 2 + ') rotate(-90)" text-anchor="middle" font-size="13" fill="#404040">' + esc(d.ytitle) + "</text>";
    return '<svg viewBox="0 0 ' + w + " " + h + '" preserveAspectRatio="none">' + o + "</svg>";
  }

  /* ---- one pane = one rectangle of rows × columns (frozen or scrolling) ---- */
  function cellsHTML(S, r0, r1, c0, c1) {
    var z = S.zoom, X = S.X, Y = S.Y, hit = "", txt = "", pad = 3 * z;
    for (var r = r0; r < r1; r++) for (var c = c0; c < c1; c++) {
      var cell = S.map[r + "," + c], st = cell ? S.d.styles[cell[3]] : null;
      var box = "left:" + px((X[c] - X[c0]) * z) + ";top:" + px((Y[r] - Y[r0]) * z) + ";height:" + px((Y[r + 1] - Y[r]) * z) + ";";
      hit += '<div class="xc" data-r="' + r + '" data-c="' + c + '" style="' + box + "width:" + px((X[c + 1] - X[c]) * z) + (st && st.bg ? ";background:" + st.bg : "") + '"></div>';
      if (!cell || cell[2] === "") continue;
      var num = cell[4], h = st.h || (num ? "right" : "left"), end = c + 1;
      // unwrapped, left-aligned text runs on over empty neighbours, as it does in Excel
      if (!num && !st.w && h === "left" && !st.bg) while (end < S.nc && !S.map[r + "," + end]) end++;
      txt += '<div class="xt" style="' + box + "width:" + px((X[end] - X[c]) * z) + ";padding:0 " + px(pad) + ";font-size:" + px(st.sz * 96 / 72 * z) +
        ";color:" + (st.c || "#000") + (st.b ? ";font-weight:700" : "") +
        ";justify-content:" + (h === "center" ? "center" : h === "right" ? "flex-end" : "flex-start") + ";text-align:" + h +
        ";align-items:" + (st.v === "top" ? "flex-start" : st.v === "center" ? "center" : "flex-end") +
        (st.w ? ";white-space:normal" : "") + (st.v === "top" ? ";padding-top:" + px(2 * z) : "") + '"><span>' + esc(cell[2]) + "</span></div>";
    }
    return hit + txt;
  }
  function drawHTML(S, r0, c0) {
    var z = S.zoom, X = S.X, Y = S.Y;
    return S.d.draw.map(function (d) {
      var l = (X[d.from[0]] - X[c0]) * z, t = (Y[d.from[1]] - Y[r0]) * z;
      if (d.t === "chart") {
        var w = X[d.to[0]] - X[d.from[0]], h = Y[d.to[1]] - Y[d.from[1]];
        return '<div class="xd" style="left:' + px(l) + ";top:" + px(t) + ";width:" + px(w * z) + ";height:" + px(h * z) + '">' + chartSVG(d, w, h) + "</div>";
      }
      return '<div class="xd" style="left:' + px(l) + ";top:" + px(t) + ";width:" + px(d.w * z) + ";height:" + px(d.h * z) + '"><img alt="" draggable="false" src="' + d.src + '"></div>';
    }).join("");
  }
  function colHdr(S, c0, c1) {
    var o = "", z = S.zoom;
    for (var c = c0; c < c1; c++) o += '<div class="xh" data-hc="' + c + '" style="left:' + px((S.X[c] - S.X[c0]) * z) + ";width:" + px((S.X[c + 1] - S.X[c]) * z) + ';height:100%">' + colName(c) + "</div>";
    return o;
  }
  function rowHdr(S, r0, r1) {
    var o = "", z = S.zoom;
    for (var r = r0; r < r1; r++) o += '<div class="xh" data-hr="' + r + '" style="top:' + px((S.Y[r] - S.Y[r0]) * z) + ";height:" + px((S.Y[r + 1] - S.Y[r]) * z) + ';width:100%">' + (r + 1) + "</div>";
    return o;
  }

  function render() {
    var S = sheets[cur], z = S.zoom, fr = S.d.fz[0], fc = S.d.fz[1], hw = HW * z, hh = HH * z;
    var fw = S.X[fc] * z, fh = S.Y[fr] * z, W = S.X[S.nc] * z, H = S.Y[S.nr] * z;
    grid.style.gridTemplateColumns = px(hw) + " " + px(fw) + " " + px(W - fw);
    grid.style.gridTemplateRows = px(hh) + " " + px(fh) + " " + px(H - fh);
    grid.style.fontSize = px(11 * z);
    function pane(cls, top, left, html) {
      return '<div class="xp ' + cls + '" style="' + (top === null ? "" : "top:" + px(top) + ";") + (left === null ? "" : "left:" + px(left) + ";") + '">' + html + "</div>";
    }
    grid.innerHTML =
      pane("x-corner", 0, 0, "") +
      pane("x-ch x-fc", 0, hw, colHdr(S, 0, fc)) +
      pane("x-ch", 0, null, colHdr(S, fc, S.nc)) +
      pane("x-rh x-fr", hh, 0, rowHdr(S, 0, fr)) +
      pane("x-tl" + (fr ? " x-fzr" : "") + (fc ? " x-fzc" : ""), hh, hw, cellsHTML(S, 0, fr, 0, fc)) +
      pane("x-tr" + (fr ? " x-fzr" : ""), hh, null, cellsHTML(S, 0, fr, fc, S.nc)) +
      pane("x-rh", null, 0, rowHdr(S, fr, S.nr)) +
      pane("x-bl" + (fc ? " x-fzc" : ""), null, hw, cellsHTML(S, fr, S.nr, 0, fc)) +
      pane("x-br", null, null, cellsHTML(S, fr, S.nr, fc, S.nc) + drawHTML(S, fr, fc));
    [].forEach.call(app.querySelectorAll(".xl-tabs button"), function (b, i) { b.classList.toggle("on", i === cur); });
    zoomLbl.textContent = Math.round(z * 100) + "%";
    view.scrollLeft = S.sx; view.scrollTop = S.sy;
    view.classList.toggle("sx", view.scrollLeft > 0);
    select(S.sel[0], S.sel[1]);
  }

  function select(r, c) {
    var S = sheets[cur], z = S.zoom, fr = S.d.fz[0], fc = S.d.fz[1], cell = S.map[r + "," + c];
    S.sel = [r, c];
    nameBox.textContent = colName(c) + (r + 1);
    fxBox.textContent = cell ? (cell.length > 5 ? cell[5] : cell[2]) : "";
    fxBox.classList.toggle("f", !!cell && cell.length > 5 && String(cell[5]).charAt(0) === "=");
    var old = grid.querySelector(".xsel"); if (old) old.remove();
    [].forEach.call(grid.querySelectorAll(".xh.on"), function (e) { e.classList.remove("on"); });
    var hc = grid.querySelector('[data-hc="' + c + '"]'), hr = grid.querySelector('[data-hr="' + r + '"]');
    if (hc) hc.classList.add("on"); if (hr) hr.classList.add("on");
    var p = grid.querySelector(r < fr ? (c < fc ? ".x-tl" : ".x-tr") : (c < fc ? ".x-bl" : ".x-br"));
    var r0 = r < fr ? 0 : fr, c0 = c < fc ? 0 : fc, s = document.createElement("div");
    s.className = "xsel";
    s.style.cssText = "left:" + px((S.X[c] - S.X[c0]) * z - 1) + ";top:" + px((S.Y[r] - S.Y[r0]) * z - 1) +
      ";width:" + px((S.X[c + 1] - S.X[c]) * z + 2) + ";height:" + px((S.Y[r + 1] - S.Y[r]) * z + 2);
    p.appendChild(s);
  }

  grid.addEventListener("click", function (e) {
    var t = e.target.closest ? e.target.closest(".xc") : null;
    if (t) select(+t.getAttribute("data-r"), +t.getAttribute("data-c"));
  });
  view.addEventListener("scroll", function () {
    var S = sheets[cur]; S.sx = view.scrollLeft; S.sy = view.scrollTop;
    view.classList.toggle("sx", view.scrollLeft > 0);
  });
  app.querySelector(".xl-tabs").addEventListener("click", function (e) {
    var b = e.target.closest ? e.target.closest("button") : null;
    if (!b) return;
    cur = +b.getAttribute("data-i"); b.blur(); render();
  });
  app.querySelector(".xl-zoom").addEventListener("click", function (e) {
    var b = e.target.closest ? e.target.closest("button") : null;
    if (!b) return;
    var S = sheets[cur], nz = Math.max(ZMIN, Math.min(ZMAX, Math.round((S.zoom + ZSTEP * +b.getAttribute("data-z")) * 100) / 100));
    S.sx = S.sx * nz / S.zoom; S.sy = S.sy * nz / S.zoom; S.zoom = nz; b.blur(); render();
  });

  render();
})();
